parameters.jsCode:
// Check severity levels
const urgent = $json.urgent || [];
const critical = urgent.filter(e => e.urgencyScore >= 0.8);
const high = urgent.filter(e => e.urgencyScore >= 0.6 && e.urgencyScore < 0.8);
const medium = urgent.filter(e => e.urgencyScore >= 0.4 && e.urgencyScore < 0.6);
const low = urgent.filter(e => e.urgencyScore < 0.4);

return {
  critical_count: critical.length,
  high_count: high.length,
  medium_count: medium.length,
  low_count: low.length,
  total_urgent: urgent.length,
  has_critical: critical.length > 0,
  critical_emails: critical.slice(0, 5)
};

