parameters.jsCode:
// Compile monitoring report
const results = $input.all();
const report = {
  timestamp: new Date().toISOString(),
  checks: results.map(r => ({
    category: r.name,
    count: (r.results || []).length,
    results: (r.results || []).slice(0, 3)
  }))
};

return report;

